import { Redwood } from 'redwood-sdk'
import { adaptError } from 'redwood-sdk/errors'

const client = new Redwood()
try {
  await client.generate({ prompt: 'hello' })
} catch (err) {
  const env = adaptError(err)
  console.log(env.human_message)
  if (env.retry_hint === 'resume' && env.resume_token) {
    // resume stream using resume token helper
    await client.stream.resume({ token: env.resume_token })
  }
}

go_snippet:
package main
import (
  "fmt"
  "github.com/redwood-inference/go-sdk/redwood"
  "github.com/redwood-inference/go-sdk/redwood/errors"
)

func main() {
  client := redwood.New()
  _, err := client.Generate(redwood.GenerateParams{Prompt: "hello"})
  if err != nil {
    env, _ := errors.AdaptError(err)
    fmt.Println(env.HumanMessage)
    if env.RetryHint == "resume" && env.ResumeToken != "" {
      // resume helper
      client.Stream.Resume(env.ResumeToken)
    }
  }
}
